"""Regression tests for the behavior specified in SPEC.md."""

import pytest

from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def session(id_, day, converted):
    return {"id": id_, "day": day, "converted": converted}


@pytest.mark.parametrize(
    "flags, expected",
    [([], 0.0), ([None], 0.0), ([True, False, None], 1 / 3),
     ([True, True], 1.0), ([False, None], 0.0)],
)
def test_conversion_rate_includes_none_in_denominator(flags, expected):
    result = conversion_rate([{"converted": flag} for flag in flags])
    assert result == expected
    assert isinstance(result, float)


def test_pooled_conversion_rate_weights_sessions_not_groups():
    groups = {
        "small": [{"converted": True}],
        "large": [{"converted": False}, {"converted": None}, {"converted": False}],
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 0.25


@pytest.mark.parametrize("groups", [{}, {"empty": []}, {"a": [], "b": []}])
def test_pooled_conversion_rate_without_sessions(groups):
    assert pooled_conversion_rate(groups) == 0.0
    assert isinstance(pooled_conversion_rate(groups), float)


@pytest.mark.parametrize(
    "counts, days, expected",
    [([1, 2, 4], 0, 0), ([1, 2, 4], 1, 4), ([1, 2, 4], 2, 6),
     ([1, 2, 4], 3, 7), ([1, 2, 4], 10, 7), ([], 0, 0), ([], 5, 0)],
)
def test_conversions_in_window(counts, days, expected):
    assert conversions_in_window(counts, days) == expected


def test_parse_session_log_flags_whitespace_and_skipped_lines():
    lines = [
        "", " \t\n", "#comment", " \t# ignored,not,a,record",
        " a , 1 , 1 \n", " b , -2 , 0 ", " c , 3 , \t",
    ]
    result = parse_session_log(iter(lines))
    assert result == [session("a", 1, True), session("b", -2, False), session("c", 3, None)]
    assert result[0]["converted"] is True
    assert result[1]["converted"] is False
    assert result[2]["converted"] is None


@pytest.mark.parametrize("line", ["a", "a,2", "a,2,1,extra", "a,no,1", "a,1.5,0", "a,,1"])
def test_parse_session_log_errors_include_original_line_number(line):
    with pytest.raises(ValueError, match=r"\bline 5\b"):
        parse_session_log(["", " # comment", "ok,1,1", " \t", line])


def test_parse_session_log_empty():
    assert parse_session_log([]) == []


def test_dedupe_sessions_keeps_last_duplicate_id_and_sorts():
    events = [
        session("b", 9, True), session("a", 2, False), session("c", 1, True),
        session("b", 2, None), session("a", 2, True),
    ]
    original = [event.copy() for event in events]
    assert dedupe_sessions(events) == [events[2], events[4], events[3]]
    assert events == original
    assert dedupe_sessions([]) == []


def test_daily_conversion_counts_inclusive_range_gaps_and_outside_sessions():
    events = [
        session("outside-before", 0, True), session("first", 1, True),
        session("missing", 2, None), session("false", 2, False),
        session("last", 4, True), session("another", 4, True),
        session("outside-after", 5, True),
    ]
    assert daily_conversion_counts(events, 1, 4) == [1, 0, 0, 2]
    assert daily_conversion_counts(events, 4, 4) == [2]
    assert daily_conversion_counts(events, 4, 1) == []
    assert daily_conversion_counts([], -1, 1) == [0, 0, 0]


@pytest.mark.parametrize("days, recent", [(0, 0), (1, 0), (2, 1), (3, 1), (10, 2)])
def test_campaign_summary_pooled_rounded_rate_calendar_window_and_active_groups(days, recent):
    groups = {
        "small": [session("a", 1, True)],
        "large": [session("b", 4, True), session("c", 5, None)],
        "empty": [],
    }
    assert campaign_summary(groups, days) == {"rate": 0.667, "recent": recent, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_campaign_summary_without_sessions(groups):
    assert campaign_summary(groups, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_converting_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [{"converted": True}],
        "empty": [],
        "middle": [{"converted": True}, {"converted": None}],
        "a": [{"converted": True}],
        "zero": [{"converted": False}],
    }
    assert top_converting_groups(groups, 2) == ["a", "z"]
    assert top_converting_groups(groups, 10) == ["a", "z", "middle", "zero"]
    assert top_converting_groups(groups, 0) == []
    assert top_converting_groups({"empty": []}, 3) == []
    assert top_converting_groups({}, 3) == []


def test_conversion_rate_by_group_sorted_keys_and_empty_group():
    groups = {
        "z": [], "b": [{"converted": True}, {"converted": None}],
        "a": [{"converted": False}],
    }
    result = conversion_rate_by_group(groups)
    assert result == {"a": 0.0, "b": 0.5, "z": None}
    assert list(result) == ["a", "b", "z"]
    assert conversion_rate_by_group({}) == {}


@pytest.mark.parametrize(
    "counts, expected",
    [([], 0), ([0, -1, 0], 0), ([1, 2, 0, 3, 4, 5], 3),
     ([1, -1, 2], 1), ([1, 2, 3, 0, 1], 3), ([1, 2, 3], 3)],
)
def test_longest_conversion_streak(counts, expected):
    assert longest_conversion_streak(counts) == expected
